package restudio.reglassneo.mixin.client;

import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.AbstractWidget;import net.minecraft.client.gui.components.Button;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.Overwrite;import restudio.reglassneo.client.api.ReGlassConfig;import restudio.reglassneo.client.api.WidgetStyle;import restudio.reglassneo.client.render.LiquidGlassRenderer;
@Mixin(AbstractWidget.class)public abstract class AbstractWidgetMixin {@Overwrite protected void renderWidget(GuiGraphics g,int mouseX,int mouseY,float partialTick){if(!((Object)this instanceof Button button))return;ReGlassConfig c=ReGlassConfig.INSTANCE;float hover=button.isHovered()?1f:0f;float enabled=button.active?1f:.55f;WidgetStyle style=WidgetStyle.create().tint(c.defaultTintColor,c.defaultTintAlpha*enabled).shadow(c.defaultShadowExpand+8f,Math.min(1f,c.defaultShadowFactor+.1f),c.defaultShadowOffsetX,c.defaultShadowOffsetY+1f).shadowColor(c.defaultShadowColor,c.defaultShadowColorAlpha).refractionFactor(c.defaultRefFactor*(.92f+.08f*hover)).fresnelFactor(c.defaultRefFresnelFactor).glareFactor(c.defaultGlareFactor).smoothing(Math.max(.02f,c.defaultSmoothing));LiquidGlassRenderer.renderCapsule(g,button.getX(),button.getY(),button.getWidth(),button.getHeight(),-1f,style);if(!button.getMessage().getString().isEmpty())g.drawCenteredString(Minecraft.getInstance().font,button.getMessage(),button.getX()+button.getWidth()/2,button.getY()+(button.getHeight()-8)/2,button.active?0xFFFFFFFF:0xFF8D919A);}}
